// Embedded PNG image data, not executable or obfuscated JavaScript.
// Generated from assets/official-logo-1024.png (48px and 180px, alpha preserved).
// Base64 is wrapped for review; decoding preserves the original PNG bytes.
const decodePng = (base64Lines: string): ArrayBuffer => {
  const base64 = base64Lines.replace(/\s/g, '');
  return Uint8Array.from(atob(base64), character => character.charCodeAt(0)).buffer;
};

